const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('en-US');
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',book:'M4 3h6a3 3 0 0 1 3 3v15a3 3 0 0 0-3-3H4z M13 6a3 3 0 0 1 3-3h5v15h-5a3 3 0 0 0-3 3',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',screen:'M3 3h18v14H3z M8 21l4-4 4 4',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',shuffle:'M3 5h3l12 14h3 M18 16l3 3-3 3 M3 19h3L18 5h3 M18 2l3 3-3 3',edit:'M16 3l5 5L8 21H3v-5z M13 6l5 5',check:'M5 12l4 4L19 6',x:'M6 6l12 12 M6 18L18 6',play:'M7 4l14 8-14 8z',pause:'M8 5v14 M16 5v14',volume:'M11 5L6 9H3v6h3l5 4z M15 8a6 6 0 0 1 0 8 M18 5a10 10 0 0 1 0 14',mute:'M11 5L6 9H3v6h3l5 4z M16 9l5 6 M16 15l5-6',trophy:'M7 3h10v6a5 5 0 0 1-10 0z M7 5H3v3a4 4 0 0 0 4 4 M17 5h4v3a4 4 0 0 1-4 4 M12 14v6 M7 21h10',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bolt:'M13 2L3 14h8l-1 8 11-13h-9z',help:'M9 8a3 3 0 1 1 4 3c-1 .5-1 1-1 3 M12 17v.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',copy:'M8 8h13v13H8z M16 8V3H3v13h5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4',menu:'M4 6h16 M4 12h16 M4 18h16',flag:'M4 22V3 M4 3h15l-3 5 3 5H4',leaf:'M20 3C8 2 1 9 5 16s17 3 15-13z M5 20L16 8',cube:'M12 2l9 5v10l-9 5-9-5V7z M3 7l9 5 9-5 M12 12v10',pencil:'M3 21l5-1L21 7l-4-4L4 16z M14 6l4 4',qr:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h2v2h4v4h-6z',exit:'M9 4H3v16h6 M12 12h9 M17 8l4 4-4 4',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.cube}"/></svg>`;
const brand=()=>`<div class="brand"><svg class="brandmark" viewBox="0 0 40 44" fill="none"><path d="M3 36L20 5l17 31H3Z" stroke="currentColor" stroke-width="2"/><path d="M10 24h20M14 36l6-12 6 12M20 5v19" stroke="currentColor" stroke-width="1.6"/><path d="M3 41h34" stroke="#d56143" stroke-width="2"/></svg><div><strong>ARCH ARENA<span style="color:var(--accent)">.</span></strong><small>THINK. PLAY. BUILD.</small></div></div>`;
const art=()=>`<svg class="hero-art" viewBox="0 0 280 165" fill="none"><defs><pattern id="grid" width="17" height="17" patternUnits="userSpaceOnUse"><path d="M17 0H0V17" stroke="#bbc2b2" stroke-width=".4"/></pattern></defs><rect width="280" height="165" fill="url(#grid)"/><g stroke="#7a8a74" stroke-width="1"><path d="M33 127l87 26 126-74-88-27zM69 117V58l44 14v58M69 58l51-31 44 14-51 31M113 130l51-30V41M126 124V89l53-31 31 9v35M126 89l31 9 53-31M157 98v45M28 130l-9 5M252 77l9-5M116 157v8"/><path d="M48 93V35l35 11v40M48 35L96 7l35 11-48 28M83 86l48-28V18"/><path d="M75 82l34 11M75 89l34 11M75 96l34 11M75 103l34 11" stroke-width=".5"/></g><path d="M129 125V91l29 9v43" stroke="#d56143" stroke-width="2"/><circle cx="233" cy="26" r="18" stroke="#adba9f"/><path d="M212 26h42M233 5v42" stroke="#adba9f" stroke-width=".5"/><text x="219" y="29" fill="#7e8a70" font-size="7" font-family="monospace">N</text></svg>`;
let S=null,room=new URLSearchParams(location.search).get('room')||'',page='board',stream=null,online=true,offset=0,hostAnswer=false,libraryFilter='',libraryCategory='',historyItems=[],allRooms=[],sound=localStorage.getItem('arch_sound')!=='false',audio=null,lastTick=-1;
const mode=location.pathname.startsWith('/join')?'player':location.pathname.startsWith('/projector')?'projector':'host';
let busy=false;
async function api(url,data){const res=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let val;try{val=await res.json()}catch{throw Error('The server could not complete this request. Please try again.')}if(!res.ok)throw Error(val.detail||'Request failed.');return val}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function beep(kind='success'){if(!sound)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='wrong'?[190,120]:kind==='tick'?[650]:kind==='final'?[220,330,440,660]:[520,660,820];notes.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.value=hz;const t=audio.currentTime+i*.12;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.08,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+.2);o.start(t);o.stop(t+.21)})}catch{}}
function subscribe(){stream?.close();stream=new EventSource(`/api/room/${room}/events${mode!=='host'?'?public=1':''}`);stream.onmessage=e=>{const n=JSON.parse(e.data),old=S;S=n;offset=n.serverNow-Date.now()/1000;online=true;updateConnection();if(mode==='host'&&page!=='board'&&old){if(!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))render();return}if(old?.current?.id!==n.current?.id)hostAnswer=false;render();if(n.current?.revealed&&!old?.current?.revealed)beep();if(n.phase==='results'&&old?.phase!=='results'){confetti();beep('final')}};stream.onerror=()=>{online=false;updateConnection()};stream.onopen=()=>{online=true;updateConnection()}}
function updateConnection(){$$('[data-connection]').forEach(x=>{x.textContent=online?'Live connection':'Reconnecting…';x.classList.toggle('offline',!online)});if(!online&&!$('#offline-banner')){$('#app').insertAdjacentHTML('afterbegin','<div id="offline-banner" class="connection-banner">Connection interrupted. Your game is saved. Reconnecting automatically…</div>')}if(online)$('#offline-banner')?.remove()}
async function action(act,extra={}){if(busy)return;busy=true;try{S=await api(`/api/room/${room}/action`,{action:act,...extra});offset=S.serverNow-Date.now()/1000;render();if(['select','board','start','final','end','reset','draw','design','rapid'].includes(act))window.scrollTo(0,0);if(act==='correct')beep();if(act==='wrong')beep('wrong');if(act==='end'){confetti();beep('final')}}catch(e){toast(e.message)}finally{busy=false}}
function cat(id){return S?.categories.find(c=>c.id===id)?.name||id}function active(){return S.teams.find(t=>t.id===S.activeTeam)||S.teams[0]}
function btn(label,act,ic='',cls='',extra=''){return `<button type="button" class="${cls}" data-action="${act}" ${extra}>${ic?icon(ic):''}${label}</button>`}
function nav(){return `<aside class="sidebar">${brand()}<div class="eyebrow">Your event</div>${[['board','Game board','grid'],['teams','Teams & players','users'],['host','Host desk','settings']].map(([id,n,i])=>btn(n,'nav',i,`navitem ${page===id?'active':''}`,`data-page="${id}"`)).join('')}<div class="eyebrow">Event studio</div>${[['library','Question library','book'],['settings','Event settings','settings'],['history','Game history','history']].map(([id,n,i])=>btn(n+(id==='library'?`<span class="count">${S.bank?.length||0}</span>`:''),'nav',i,`navitem ${page===id?'active':''}`,`data-page="${id}"`)).join('')}<div class="sidebar-bottom">${btn('How to play','help','help','navitem')}<div class="room-mini"><span class="eyebrow" style="margin:0;font-size:8px">YOUR GAME ROOM</span><b>${esc(room)}</b>${btn('Invite players','invite','qr','small')}</div><div class="profile"><div class="avatar">AD</div><div><b>Event organizer</b><small>Host workspace</small></div>${btn('','recovery','lock','quiet small','title="Save host recovery key"')}</div></div></aside>`}
function header(){return `<header class="topbar">${btn('','menu','menu','quiet mobile-menu','aria-label="Open navigation"')}<div class="breadcrumb">Event workspace ${icon('chevron')} <b>${esc(S.name)}</b></div><div class="top-actions"><span class="status ${online?'':'offline'}" data-connection>${online?'Live connection':'Reconnecting…'}</span><span class="vertical"></span>${btn('Presentation mode','projector','screen','small')}${btn('Invite players','invite','plus','primary small')}</div></header>`}
function render(){if(!S)return;document.documentElement.style.setProperty('--accent',/^#[0-9a-f]{6}$/i.test(S.accent)?S.accent:'#d56143');if(mode==='host')$('#app').innerHTML=`${nav()}<div class="workspace">${header()}<main>${page==='board'?gameContent():page==='teams'?teamsPage():page==='library'?libraryPage():page==='settings'?settingsPage():page==='history'?historyPage():hostPage()}<div class="footer-note"><span>ARCH ARENA &nbsp; / &nbsp; A SPACE FOR CURIOUS MINDS</span><span>${icon('lock')} Server-saved · ${esc(room)}</span></div>${S.sponsors?`<div class="sponsor">With the support of ${esc(S.sponsors)}</div>`:''}</main></div>`;else if(mode==='projector')renderProjector();else renderPlayer();tick();updateConnection()}
function hero(){return `<section class="hero"><div><div class="eyebrow"><span style="width:18px;height:1px;background:var(--accent)"></span> The architecture quiz show</div><h1>${esc(S.name)}</h1><p>Big ideas. Bold answers. A little friendly competition.</p></div><div class="hero-right">${art()}<span class="roundbadge">ROUND 01 / THE CHALLENGE</span></div></section>`}
function scores(interactive=true){const rank=[...S.teams].sort((a,b)=>b.score-a.score);return `<div class="scores-heading"><h2 class="section-title">${icon('trophy')} Live scoreboard</h2><span class="subtext">${S.teams.length} teams · ${S.participants} participants</span></div><div class="scores">${S.teams.map((t,i)=>`<${interactive?'button':'div'} class="team-card ${t.id===S.activeTeam?'selected':''}" style="--team:${esc(t.color)}" ${interactive?`data-action="active" data-team="${esc(t.id)}"`:''}><div class="team-top"><span class="team-symbol">${t.logo?`<img src="${esc(safeImage(t.logo))}" alt="">`:icon(['pencil','cube','spark','grid'][i%4])}</span>${esc(t.name)}</div><div class="team-score">${fmt(t.score)}<small>pts</small></div><span class="team-state">${t.id===S.activeTeam?'Your turn':rank[0].id===t.id&&t.score>0?'Leading':'Team '+(i+1)}</span></${interactive?'button':'div'}>`).join('')}</div>`}
function boardPage(){const played=S.board.filter(q=>S.used.includes(q.id)).length;return `${hero()}<div class="board-heading"><h2 class="section-title">Choose your challenge <span class="subtext">/ ${S.selected.length} categories · ${S.board.length} questions</span></h2>${mode==='host'?`<div class="board-tools">${btn('Shuffle','random','shuffle','small quiet')}${btn('Edit categories','categories','settings','small')}</div>`:''}</div><div class="turn-banner">${icon(S.phase==='lobby'?'spark':'flag')}<span>${S.phase==='lobby'?'<b>The stage is yours.</b> Start the game, or pick a question to begin.':`<b>${esc(active().name)}, you’re up.</b> Choose a category and point value.`}</span><span class="right"><span class="dot" style="background:#859a70"></span>${S.phase==='lobby'?'READY TO PLAY':'GAME IN PROGRESS'}</span></div><div class="board">${S.selected.map(id=>{const c=S.categories.find(c=>c.id===id),qs=S.board.filter(q=>q.category===id).sort((a,b)=>a.difficulty-b.difficulty);return `<article class="category"><div class="category-image"><img src="${esc(safeImage(c.image))}" alt="${esc(c.name)} architectural inspiration" onerror="this.style.display='none'"><span class="category-no">${esc(c.number)}</span><div class="category-label"><h3>${esc(c.name)}</h3><small>${qs.length} QUESTIONS · ${qs.length?Math.min(...qs.map(q=>q.points)):0}–${qs.length?Math.max(...qs.map(q=>q.points)):0} PTS</small></div></div>${qs.map(q=>`<button class="point ${S.used.includes(q.id)?'used':''}" data-action="select" data-id="${esc(q.id)}" ${S.used.includes(q.id)||mode!=='host'?'disabled':''} aria-label="${esc(c.name)} for ${q.points} points">${S.used.includes(q.id)?icon('check'):fmt(q.points)}<span>PTS</span></button>`).join('')}${!qs.length?'<div class="empty" style="padding:35px 8px;font-size:11px">Add questions for this difficulty in the library.</div>':''}</article>`}).join('')}</div><div class="board-note"><span>${icon('help')} Higher points. Greater challenge.</span><span>${played} / ${S.board.length} completed <span style="display:inline-block;width:80px;height:3px;background:#e2e4d8;border-radius:2px"><span style="display:block;background:#91a17c;height:3px;width:${played/Math.max(1,S.board.length)*100}%"></span></span></span><span>${icon('bolt')} Watch for double-point questions</span></div>${scores(mode==='host')}${mode==='host'?boardControls():''}`}
function boardControls(){return `<div class="footer-controls"><div class="left"><span class="control-label">${icon('settings')} HOST CONTROLS</span>${S.phase==='lobby'?btn('Start game','start','play','dark'):btn('Host desk','nav','settings','','data-page="host"')}${btn('Special rounds','rounds','bolt')}${btn('Final challenge','final','flag','quiet')}</div><div class="right">${btn('','sound',sound?'volume':'mute','quiet icon',`title="${sound?'Mute':'Enable'} sound" aria-label="Toggle sound"`)}${btn('End game','end','exit','quiet small')}</div></div>`}
function safeImage(v){return /^\/assets\/[a-zA-Z0-9._-]+$/.test(v)?v:''}
function questionView(isHost=false){const q=S.current;if(!q)return '';const visual=!!safeImage(q.image);return `<section class="question-stage ${q.revealed?'revealed-stage':''}"><div class="question-meta"><span>${esc(cat(q.category))} <span style="opacity:.5">/ ${esc(q.mode==='standard'?q.type:q.mode+' round')}</span></span><span class="question-value">${q.mode==='final'?'FINAL CHALLENGE':fmt(q.points*q.multiplier)+' POINTS'} ${q.multiplier===2?'⚡ DOUBLE':''} ${q.steal?'· STEAL':''}</span></div><h1>${esc(q.question)}</h1><div class="question-content ${visual?'visual':''}">${visual?`<img class="question-image" src="${esc(safeImage(q.image))}" alt="Visual question — architectural reference" onerror="this.outerHTML='<div class=&quot;image-error&quot;>Image unavailable. Host: skip or replace this question.</div>'">`:''}<div>${q.options?.length?`<div class="options">${q.options.map((o,i)=>`<div class="answer-option ${q.revealed&&o===q.correctAnswer?'correct':''} ${q.hidden.includes(o)?'hidden':''}"><span class="letter">${'ABCDEFGH'[i]||i+1}</span>${esc(o)}${q.revealed&&o===q.correctAnswer?icon('check'):''}</div>`).join('')}</div>`:!q.revealed?`<p style="color:var(--muted);line-height:1.6">${q.mode==='draw'?'Pencils ready. You have 60 seconds.':q.mode==='design'?'Creativity · Function · Sustainability · Aesthetics · Presentation':q.mode==='final'?'Discuss with your team. Write down your complete answer.':'No options. Just your architectural knowledge.'}</p>`:''}</div></div>${q.hintShown?`<div class="hint">${icon('help')} <b>Site analysis:</b> ${esc(q.hintText)}</div>`:''}${q.revealed?`<div class="answer-reveal"><div class="eyebrow">Correct answer</div><strong>${esc(q.correctAnswer)}</strong><p>${esc(q.explanation)}</p></div>${distribution(q)}`:''}<div class="timer-wrap"><span class="timer" data-timer>00:30</span><div class="timer-track"><div class="timer-fill" data-timer-fill></div></div><span class="subtext">${q.revealed?'Answer revealed':q.paused?'Timer paused':q.submissions+' answers locked'}</span></div></section>${isHost?questionControls():''}`}
function distribution(q){const d=q.distribution;if(!d||!Object.keys(d).length||!q.submissions)return '';return `<div class="distribution"><div class="eyebrow">Audience response · ${q.submissions} answers</div>${Object.entries(d).map(([o,n])=>`<div class="dist-row"><span class="dist-label">${esc(o)}</span><div class="dist-bar"><span style="width:${n/q.submissions*100}%"></span></div><b>${Math.round(n/q.submissions*100)}%</b></div>`).join('')}</div>`}
function questionControls(){const q=S.current;return `<div class="host-only">${icon('lock')}<div style="flex:1"><span class="eyebrow">Host eyes only · never shown on the projector</span>${hostAnswer?`<b>${esc(q.correctAnswer)}</b><small>${esc(q.explanation)}</small>`:''}</div>${btn(hostAnswer?'Hide answer':'Peek at answer','peek','eye','small quiet')}</div><div class="host-actions"><select id="active-team" aria-label="Answering team">${S.teams.map(t=>`<option value="${esc(t.id)}" ${t.id===S.activeTeam?'selected':''}>${esc(t.name)}</option>`).join('')}</select>${q.mode!=='final'?`${btn('Correct','correct','check','success',q.awarded.length?'disabled':'')}${btn(q.mode==='rapid'?'Wrong / 0 points':'Wrong / steal','wrong','x','',q.revealed||q.awarded.length?'disabled':'')}`:''}${btn('Reveal answer','reveal','eye','dark',q.revealed?'disabled':'')}${btn(q.paused?'Resume':'Pause','pause',q.paused?'play':'pause','',q.revealed?'disabled':'')}${btn('2× points','double','bolt','',q.revealed?'disabled':'')}${btn(q.revealed?'Next question':'Skip question','board','arrow','quiet')}${q.mode==='rapid'?btn('Next rapid question','rapidNext','bolt','primary'):''}</div>${q.mode==='final'&&q.revealed?`<div class="panel"><h2>Judge final answers</h2>${S.teams.map(t=>`<div class="leader-row"><span style="flex:1">${esc(t.name)} · wager ${fmt(S.wagers[t.id])}</span>${t.id in S.finalResults?`<b>${S.finalResults[t.id]>=0?'+':''}${fmt(S.finalResults[t.id])}</b>`:`${btn('Correct','finalJudge','check','small success',`data-team="${esc(t.id)}" data-correct="true"`)}${btn('Incorrect','finalJudge','x','small',`data-team="${esc(t.id)}" data-correct="false"`)}`}</div>`).join('')}${btn('Show final results','end','trophy','primary','style="margin-top:20px"')}</div>`:''}${S.settings.powers&&!q.revealed?`<div class="power-row"><span class="eyebrow">Team power-ups</span>${[['blueprint','Blueprint','grid'],['support','+10 seconds','clock'],['analysis','Site analysis','help'],['consult','Team huddle +15s','users']].map(([id,n,i])=>btn(n,'power',i,'small',`data-power="${id}" ${active().powers.includes(id)?'disabled':''}`)).join('')}</div>`:''}${scores()}${q.mode==='draw'||q.mode==='design'?`<div class="panel" style="margin-top:20px"><h2>Manual judging</h2><p>${q.mode==='design'?'Score each of five criteria from 0 to 100, then enter the team’s total (up to 500).':'Award points for spatial clarity, architectural details, and communication.'}</p>${btn('Award / adjust points','adjust','plus')}</div>`:''}`}
function gameContent(){if(S.phase==='question')return questionView(true);if(S.phase==='wagers')return wagersPage(true);if(S.phase==='results')return resultsPage();return boardPage()}
function wagersPage(isHost=false){return `<div class="winner"><div class="eyebrow">The final architecture challenge</div><div class="trophy">${icon('flag')}</div><h1>One last bold move.</h1><p>Every team locks a secret wager. Back your knowledge.</p></div><div class="panel">${S.teams.map(t=>`<div class="leader-row"><span class="team-symbol" style="--team:${esc(t.color)}">${icon('cube')}</span><span>${esc(t.name)}<small style="display:block;color:var(--muted)">${fmt(t.score)} points available</small></span><span style="margin-left:auto" class="badge">${S.wagersReady.includes(t.id)?'✓ Wager locked':'Deciding…'}</span>${isHost&&!S.wagersReady.includes(t.id)?btn('Enter wager','wager','','small',`data-team="${esc(t.id)}"`):''}</div>`).join('')}${isHost?`<p>Team captains can wager privately on their phones. For offline teams, enter their written wager here. Wager amounts are hidden from the projector.</p>${btn('Reveal final question','finalStart','arrow','primary',S.wagersReady.length!==S.teams.length?'disabled':'')}`:''}</div>`}
function resultsPage(){const ranked=[...S.teams].sort((a,b)=>b.score-a.score),win=ranked.filter(t=>t.score===ranked[0].score);return `<div class="winner"><div class="eyebrow">${esc(S.name)} · Final results</div><div class="trophy">${icon('trophy')}</div><span class="badge">${win.length>1?'JOINT WINNERS':'THE WINNER'}</span><h1>${win.map(t=>esc(t.name)).join(' & ')}</h1><div class="winning-score">${fmt(ranked[0].score)} points</div><p>Well played. Well designed.</p></div><div class="grid2"><div class="panel"><h2>Final team rankings</h2>${ranked.map((t,i)=>`<div class="leader-row"><span class="leader-rank">${String(i+1).padStart(2,'0')}</span><span>${esc(t.name)}</span><b>${fmt(t.score)}</b></div>`).join('')}</div><div class="panel"><h2>Audience leaderboard</h2>${leaderboard()}</div></div>${mode==='host'?`<div class="host-actions">${btn('View game history','nav','history','','data-page="history"')}${btn('New event','newEvent','plus','primary')}${btn('Reset this game','reset','history','quiet danger')}</div>`:''}`}
function leaderboard(){return S.leaderboard.length?S.leaderboard.slice(0,15).map((p,i)=>`<div class="leader-row"><span class="leader-rank">${String(i+1).padStart(2,'0')}</span><span>${esc(p.name)} ${p.streak>=2?`<span class="badge">${p.streak} streak</span>`:''}</span><b>${fmt(p.score)}</b></div>`).join(''):'<div class="empty" style="padding:35px">No audience players yet. Invite them with your room QR code.</div>'}
function title(name,desc,button=''){return `<div class="page-title"><div><h1>${name}</h1><p>${desc}</p></div>${button}</div>`}
function teamsPage(){return `${title('The people behind the points.','Create teams, welcome your audience, and keep the competition moving.',btn('Add team','teamEdit','plus','primary'))}<div class="stat-grid"><div class="stat"><b>${S.teams.length}</b><span>Competing teams</span></div><div class="stat"><b>${S.participants}</b><span>Audience players</span></div><div class="stat"><b>${fmt(S.teams.reduce((s,t)=>s+t.score,0))}</b><span>Points on the board</span></div></div><div class="grid2">${S.teams.map(t=>`<div class="panel"><div style="display:flex;align-items:center;gap:12px"><span class="team-symbol" style="--team:${esc(t.color)}">${icon('cube')}</span><h2 style="margin:0;flex:1">${esc(t.name)}</h2>${btn('','teamEdit','edit','small quiet',`data-id="${esc(t.id)}" aria-label="Edit team"`)}</div><p>${S.leaderboard.filter(p=>p.team===t.id).length} participants · ${t.powers.length} power-ups used</p><div style="display:flex;align-items:center;justify-content:space-between"><strong style="font-size:32px;font-family:Manrope">${fmt(t.score)} <small style="font-size:12px;color:var(--muted)">pts</small></strong>${btn('Adjust score','adjust','plus','small',`data-team="${esc(t.id)}"`)}</div></div>`).join('')}</div><div class="panel"><div class="board-heading"><h2>Audience leaderboard</h2>${btn('Invite players','invite','qr','small')}</div><p>Audience answers earn 100 points each. Team scores are judged separately by the host.</p>${leaderboard()}</div>`}
function libraryPage(){return `${title('A library of big ideas.',`${S.bank.length} questions. Endless conversations. Make this event your own.`,btn('Add question','questionEdit','plus','primary'))}<div class="library-toolbar"><input id="library-search" placeholder="Search questions, answers, or keywords…" value="${esc(libraryFilter)}"><select id="library-category"><option value="">All categories</option>${S.categories.map(c=>`<option value="${esc(c.id)}" ${c.id===libraryCategory?'selected':''}>${esc(c.name)}</option>`).join('')}</select>${btn('Final prompt','questionEdit','flag','small','data-id="final-1"')}${btn('Categories','manageCategories','settings','small')}${btn('Export','export','download','small')}</div><div class="panel" style="padding:14px 18px;font-size:12px;color:#7a836e">${icon('book')} &nbsp; Editorial question bank · Review facts, image rights, and difficulty against your curriculum before the event. Add campus photos for a local challenge.</div><div id="library-table">${libraryTable()}</div>`}
function libraryTable(){const qs=S.bank.filter(q=>(!libraryCategory||q.category===libraryCategory)&&(!libraryFilter||[q.question,q.correctAnswer,cat(q.category)].join(' ').toLowerCase().includes(libraryFilter.toLowerCase())));return `<div class="table-wrap"><table><thead><tr><th>Question</th><th>Category</th><th>Format</th><th>Points</th><th>Manage</th></tr></thead><tbody>${qs.map(q=>`<tr><td>${q.image?'<span class="badge">VISUAL</span> ':''}${esc(q.question)}</td><td>${esc(cat(q.category))}</td><td><span class="badge">${esc(q.type)}</span></td><td><b>${q.points}</b></td><td><div class="table-actions">${btn('','questionEdit','edit','small quiet',`data-id="${esc(q.id)}" aria-label="Edit question"`)}${btn('','duplicate','copy','small quiet',`data-id="${esc(q.id)}" aria-label="Duplicate question"`)}${btn('','questionDelete','trash','small quiet danger',`data-id="${esc(q.id)}" aria-label="Delete question"`)}</div></td></tr>`).join('')}</tbody></table>${!qs.length?'<div class="empty">No questions match. Try another category or search.</div>':''}</div>`}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}" ${String(Array.isArray(o)?o[0]:o)===String(value)?'selected':''}>${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select></div>`}
function settingsPage(){return `${title('Set the stage.','Your event, your rules, your identity.',btn('Save settings','saveSettings','check','primary'))}<form id="settings-form"><div class="grid2"><div class="panel"><h2>Event identity</h2><p>Built for your university. No fixed branding.</p>${field('Event name','name',S.name,'text','required maxlength="100"')}${field('Department','department',S.department)}${field('University','university',S.university)}${field('Event date','eventDate',S.eventDate,'date')}${field('Sponsors / acknowledgements','sponsors',S.sponsors)}<div class="grid2">${field('Accent color','accent',S.accent,'color')}<div class="field"><label>Event logo</label><input type="file" data-upload="eventLogo" accept="image/*"><input type="hidden" id="eventLogo" name="logo" value="${esc(S.logo)}">${S.logo?`<img class="preview-thumb" src="${esc(safeImage(S.logo))}" alt="Event logo">`:''}</div></div><div class="field"><label>Projector background (optional)</label><input type="file" data-upload="eventBackground" accept="image/*"><input type="hidden" id="eventBackground" name="background" value="${esc(S.background)}"><small>Displayed subtly behind projector content.</small></div></div><div><div class="panel"><h2>Rules of play</h2><p>Simple controls. Fair competition.</p><div class="grid2">${selectField('Question timer','timer',[10,15,20,30,60],S.settings.timer)}${selectField('Difficulty range','difficulty',[['easy','Easy · levels 1–2'],['normal','Normal · all levels'],['hard','Hard · levels 3–5'],['expert','Expert · levels 4–5']],S.settings.difficulty)}</div><div class="grid2">${field('Steal value (%)','steal',S.settings.steal,'number','min="0" max="100"')}${field('Double-point chance (%)','doubleChance',S.settings.doubleChance,'number','min="0" max="100"')}</div><label class="check-row"><input type="checkbox" name="powers" ${S.settings.powers?'checked':''}>Enable team power-ups</label><label class="check-row"><input type="checkbox" name="penalty" ${S.settings.penalty?'checked':''}>Deduct question value for incorrect team answers</label><p style="font-size:11px">The board draws one question per difficulty per category. A narrower difficulty range creates a shorter round. Used questions cannot be replayed.</p></div><div class="panel"><h2>Game sets & presets</h2><p>Create a fresh event, or duplicate this setup with scores reset.</p><div class="host-actions">${btn('New game set','newEvent','plus')}${btn('Duplicate setup','cloneEvent','copy')}${btn('Switch event','switchEvent','grid')}</div></div><div class="panel"><h2>Host access & recovery</h2><p>Your browser holds a private host session. Save its recovery key to access your events on another device.</p>${btn('Save recovery key','recovery','lock')} ${btn('Restore host access','restore','history','quiet small')}</div></div></div></form><div class="panel"><h2>Start fresh</h2><p>Reset scores, participants, power-ups, and question progress. Completed game history is kept.</p>${btn('Reset this game','reset','history','danger')}</div>`}
function historyPage(){return `${title('Every game tells a story.','Completed events, final rankings, and the moments that mattered.',btn('Refresh','refreshHistory','history'))}${historyItems.length?historyItems.map(h=>`<div class="panel"><div class="board-heading"><div><div class="eyebrow">${new Date(h.date*1000).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</div><h2 style="margin-top:10px">${esc(h.name)}</h2></div><span class="badge">COMPLETED</span></div><p>${h.participants} participants · ${h.questions} questions played · ${esc(h.code)}</p>${[...h.teams].sort((a,b)=>b.score-a.score).map((t,i)=>`<div class="leader-row"><span class="leader-rank">${i+1}</span>${esc(t.name)}<b>${fmt(t.score)}</b></div>`).join('')}<div class="host-actions">${btn('Download results','downloadHistory','download','small',`data-id="${esc(h.id)}"`)}${btn('View scoring log','historyLog','history','small quiet',`data-id="${esc(h.id)}"`)}</div></div>`).join(''):`<div class="panel empty">${icon('history')}<h2>Your first chapter is waiting.</h2><p>End a game to save its final rankings here.</p>${btn('Back to the board','nav','arrow','primary','data-page="board"')}</div>`}`}
function hostPage(){return `${title('You’re in control.','Everything you need to run a smooth Architecture Day.')}<div class="turn-banner"><span class="status">${esc(S.phase)}</span><span style="margin-left:15px">${S.current?esc(S.current.question):'Choose a challenge on the board to begin.'}</span></div>${S.current?questionView(true):`${scores()}<div class="panel" style="margin-top:20px"><h2>Run your event</h2><div class="host-actions">${btn('Open game board','nav','grid','dark','data-page="board"')}${btn('Invite audience','invite','qr')}${btn('Presentation mode','projector','screen')}${btn('Special rounds','rounds','bolt')}${btn('Final challenge','final','flag')}${btn('Adjust points','adjust','plus')}${btn('End game','end','exit','quiet danger')}</div></div>`}<div class="panel"><h2>Scoring activity</h2>${S.log?.length?S.log.slice().reverse().map(l=>`<div class="leader-row"><span class="subtext">${new Date(l.time*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span>${esc(l.text)}</div>`).join(''):'<p>Score changes will appear here as the game progresses.</p>'}</div>`}
function renderProjector(){const background=safeImage(S.background);$('#app').innerHTML=`<div class="public-view" ${background?`style="background-image:linear-gradient(#f4f2e8ed,#f4f2e8ed),url('${esc(background)}');background-size:cover"`:''}><div class="public-head">${S.logo?`<img src="${esc(safeImage(S.logo))}" alt="Event logo" style="max-width:150px;max-height:55px">`:brand()}<div style="text-align:center"><h2 style="margin:0">${esc(S.department)}</h2><small>${esc(S.university)}</small></div><div style="display:flex;align-items:center;gap:12px"><span class="status" data-connection>Live connection</span>${btn('','fullscreen','screen','quiet','title="Fullscreen"')}${btn('','sound',sound?'volume':'mute','quiet','title="Toggle sound"')}</div></div><main>${S.phase==='question'?questionView()+scores(false):S.phase==='results'?resultsPage():S.phase==='wagers'?wagersPage():boardPage()}${S.phase==='lobby'?`<div class="join-strip" style="margin-top:20px"><img src="/api/room/${room}/qr" alt="Scan to join"><div>Bring your architectural knowledge.<strong>${esc(room)}</strong><small>Scan to join · ${S.participants} players connected</small></div></div>`:''}${S.sponsors?`<div class="sponsor">With the support of ${esc(S.sponsors)}</div>`:''}</main></div>`}
function renderJoin(){const r=esc(room);$('#app').innerHTML=`<div class="join-shell"><header class="join-header">${brand()}<a href="/" class="subtext">Host an event ${icon('arrow')}</a></header><div class="join-main"><div class="eyebrow">Your next big idea starts here</div><h1>Great minds.<br>Good competition.</h1><p>A quiz show for people who see the world a little differently. Join your team and build your way to the top.</p><form id="join-form" class="panel">${field('Room code','room',r,'text','required placeholder="ARCH-A1B2C3" autocapitalize="characters"')}${field('Your nickname','name','','text','required maxlength="35" placeholder="What should we call you?"')}${S?selectField('Choose your team','team',S.teams.map(t=>[t.id,t.name]),S.teams[0]?.id):'<div class="field"><small>Enter a room code to load its teams.</small></div>'}<button class="primary" type="submit">${S?'Join the challenge':'Find my room'} ${icon('arrow')}</button></form><div class="join-foot">No account needed. Just curiosity.</div></div></div>`}
function renderPlayer(){const previousId=$('#answer-form')?.dataset.qid;const previousAnswer=$('#answer-form [name=answer]')?.value;const previousFocus=document.activeElement?.name==='answer';if(!S.me){renderJoin();return}const me=S.me,q=S.current;let body='';if(S.phase==='question'){body=`<section class="question-stage"><div class="question-meta"><span>${esc(cat(q.category))}</span><span class="question-value">${q.mode==='final'?'FINAL':'100 AUDIENCE PTS'}</span></div><h1>${esc(q.question)}</h1>${q.image?`<img class="question-image" src="${esc(safeImage(q.image))}" alt="Architecture question image">`:''}${q.revealed?`<div class="answer-reveal"><div class="eyebrow">Correct answer</div><strong>${esc(q.correctAnswer)}</strong><p>${esc(q.explanation)}</p></div>${distribution(q)}`:q.mode==='final'?'<div class="hint">Write your team’s answer and give it to the host. Final wagers are judged together.</div>':q.type==='drawing'?'<div class="hint">This is an offline team challenge. Follow the host’s instructions.</div>':q.submitted?`<div class="answer-reveal"><strong>${icon('lock')} Answer locked.</strong><p>Watch the big screen for the reveal.</p></div>`:`<form id="answer-form" data-qid="${esc(q.id)}">${q.options.length?`<div class="options">${q.options.map((o,i)=>`<button type="button" data-action="chooseAnswer" data-answer="${esc(o)}" class="answer-option ${q.hidden.includes(o)?'hidden':''}" ${q.hidden.includes(o)?'disabled':''}><span class="letter">${'ABCDEFGH'[i]}</span>${esc(o)}</button>`).join('')}</div><input type="hidden" name="answer" id="chosen-answer">`:`<div class="field"><label>Your answer</label><input name="answer" required autocomplete="off" placeholder="Type your answer…" maxlength="600"></div>`}<button class="primary" type="submit" data-submit-answer style="width:100%">Lock my answer ${icon('lock')}</button></form>`}${q.hintShown?`<div class="hint" style="margin-top:15px">${esc(q.hintText)}</div>`:''}<div class="timer-wrap"><span class="timer" data-timer></span><div class="timer-track"><div class="timer-fill" data-timer-fill></div></div><span class="subtext">${q.paused?'Paused':q.revealed?'Revealed':'Time remaining'}</span></div></section>`}else if(S.phase==='wagers'){body=wagersPage(false);if(me.captain&&!S.wagersReady.includes(me.team))body+=`<form id="player-wager-form" class="panel"><h2>Your team’s secret wager</h2><p>You are the first player on this team, so you control its wager. Discuss privately before locking.</p>${field('Wager points','amount',0,'number',`min="0" max="${Math.max(0,S.teams.find(t=>t.id===me.team).score)}" required`)}<button type="submit" class="primary">Lock secret wager ${icon('lock')}</button></form>`}else if(S.phase==='results')body=resultsPage();else body=`<div class="panel empty"><div class="eyebrow">${esc(S.name)}</div><div style="margin:25px 0">${icon('spark')}</div><h2>You’re on the team.</h2><p>The host is ${S.phase==='lobby'?'getting the stage ready':'choosing the next question'}.<br>Stay here — the challenge will appear automatically.</p><span class="badge">${esc(S.teams.find(t=>t.id===me.team)?.name)}</span></div>${scores(false)}`;$('#app').innerHTML=`<div class="join-shell"><header class="join-header">${brand()}<span class="status" data-connection>Live connection</span></header><div class="participant-main"><div class="participant-info"><div><b>${esc(me.name)}</b><small style="display:block;color:var(--muted);margin-top:4px">${esc(S.teams.find(t=>t.id===me.team)?.name)}</small></div><span class="badge">${fmt(me.score)} points ${me.streak>=2?' · '+me.streak+' streak':''}</span></div>${body}<div class="join-foot">${esc(room)} · Keep this browser to reconnect with your score.</div></div></div>`;if(previousId===q?.id&&previousAnswer&&$('#answer-form')){const inp=$('#answer-form [name=answer]');inp.value=previousAnswer;$$('[data-action=chooseAnswer]').forEach(b=>b.classList.toggle('chosen',b.dataset.answer===previousAnswer));if(previousFocus)inp.focus()}}
function tick(){if(!S?.current)return;const q=S.current,seconds=q.revealed?0:Math.max(0,Math.ceil(q.paused?q.remaining:q.deadline-(Date.now()/1000+offset)));$$('[data-timer]').forEach(el=>{el.textContent=q.revealed?'✓':seconds===0?'TIME':`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;el.classList.toggle('dramatic',seconds>0&&seconds<=5&&!q.paused)});$$('[data-timer-fill]').forEach(el=>el.style.width=(Math.min(100,seconds/(q.duration||S.settings.timer)*100))+'%');$$('[data-submit-answer]').forEach(el=>el.disabled=seconds===0||q.paused);if(seconds<=5&&seconds>0&&!q.paused&&!q.revealed&&lastTick!==seconds){lastTick=seconds;beep('tick')}if(seconds>5)lastTick=-1}
setInterval(tick,200);
function modal(title,content,wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2>${btn('','close','x','quiet icon','aria-label="Close dialog"')}</div>${content}</section></div>`;setTimeout(()=>$('.modal input:not([type=hidden]),.modal button')?.focus(),30)}
function close(){ $('#modal-root').innerHTML=''}
function confirmModal(title,text,act){modal(title,`<p>${text}</p><div class="modal-footer">${btn('Cancel','close')}${btn('Confirm','confirmed','check','primary',`data-confirm="${act}"`)}</div>`)}
function invite(){const url=location.origin+'/join?room='+room;modal('Good competition starts with good company.',`<p>Scan the code, choose a nickname, and join a team. No app or account required.</p><div class="qr-layout"><img src="/api/room/${room}/qr" alt="QR code to join this game"><div><div class="eyebrow">Your room code</div><strong class="room-code">${esc(room)}</strong><p>${S.participants} audience players joined</p>${btn('Copy join link','copyLink','copy','primary')}<a href="${esc(url)}" target="_blank" rel="noopener" style="display:block;margin-top:15px;font-size:12px;text-decoration:underline">Open participant page ↗</a></div></div><p style="font-size:11px">Keep the host workspace private. Share only this participant link.</p>`)}
function categoriesModal(){modal('Curate your challenge.',`<p>Choose up to six categories. Each one brings a different perspective to the board.</p><form id="categories-form"><div class="category-picker">${S.categories.map(c=>`<label class="category-pick"><input type="checkbox" name="category" value="${esc(c.id)}" ${S.selected.includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')}</div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="primary">Save categories ${icon('check')}</button></div></form>`,true)}
function teamModal(id){const t=S.teams.find(x=>x.id===id)||{name:'',color:'#d56143',logo:''};modal(id?'Refine your team.':'Meet your next team.',`<form id="team-form" data-id="${esc(id||'')}">${field('Team name (or individual player name)','name',t.name,'text','required maxlength="40"')}${field('Team color','color',t.color,'color')}<div class="field"><label>Team logo (optional)</label><input type="file" data-upload="teamLogo" accept="image/*"><input type="hidden" name="logo" id="teamLogo" value="${esc(t.logo)}"></div><div class="modal-footer">${id?btn('Delete team','teamDelete','trash','danger quiet',`data-id="${esc(id)}"`):''}${btn('Cancel','close')}<button class="primary" type="submit">Save team ${icon('check')}</button></div></form>`)}
function questionModal(id,duplicate=false){let q=(id==='final-1'?S.finalQuestion:S.bank.find(q=>q.id===id))||{category:S.categories[0].id,difficulty:1,points:100,type:'open',options:[],timeLimit:30};if(duplicate)q={...q,id:''};modal(duplicate?'A new take on a great question.':id?'Refine the question.':'Add to the conversation.',`<form id="question-form" data-id="${esc(q.id||'')}"><div class="grid2">${selectField('Category','category',S.categories.map(c=>[c.id,c.name]),q.category)}${selectField('Question format','type',[['open','Open / rapid answer'],['choice','Multiple choice'],['truefalse','True / false'],['image','Image / building / architect ID'],['match','Match the pairs'],['timeline','Timeline / which came first'],['estimate','Estimate (numeric tolerance)'],['drawing','Sketch / design judgement']],q.type)}</div><div class="field"><label>Question</label><textarea name="question" required>${esc(q.question||'')}</textarea></div><div class="grid2">${selectField('Difficulty','difficulty',[[1,'1 · Easy'],[2,'2 · Medium'],[3,'3 · Moderate'],[4,'4 · Hard'],[5,'5 · Very hard']],q.difficulty)}${field('Point value','points',q.points,'number','min="0" max="10000" required')}</div><div class="grid2"><div class="field"><label>Answer options (one per line, optional)</label><textarea name="options" placeholder="Option A&#10;Option B&#10;Option C&#10;Option D">${esc(q.options.join('\n'))}</textarea></div><div class="field"><label>Correct answer</label><textarea name="correctAnswer" required placeholder="For choices, match an option exactly.">${esc(q.correctAnswer||'')}</textarea><small>Open answers: separate accepted variants with |. Host judges conceptual answers.</small></div></div><div class="field"><label>Educational explanation</label><textarea name="explanation">${esc(q.explanation||'')}</textarea></div><div class="grid2">${field('Question time limit (seconds)','timeLimit',q.timeLimit,'number','min="10" max="300"')}${field('Estimate tolerance (±)','tolerance',q.tolerance||0,'number','min="0" step="any"')}</div>${field('Site analysis clue','hint',q.hint||'')}${field('Source / reference / image credit','source',q.source||'')}<div class="field"><label>Question image / campus photograph</label><input type="file" data-upload="questionImage" accept="image/*"><input type="hidden" name="image" id="questionImage" value="${esc(q.image||'')}"><small>PNG, JPEG, or WebP · up to 5 MB · use images you have permission to display.</small><div id="image-preview">${q.image?`<img class="preview-thumb" src="${esc(safeImage(q.image))}" alt="Question image">`:''}</div></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="primary">Save question ${icon('check')}</button></div></form>`,true)}
function adjustModal(tid){modal('A little fine-tuning.',`<form id="adjust-form">${selectField('Team','team',S.teams.map(t=>[t.id,t.name]),tid||S.activeTeam)}${field('Point adjustment','amount',100,'number','required min="-100000" max="100000"')}<p>Use a negative number to remove points. Every adjustment is recorded in the host’s scoring log.</p><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="primary">Apply adjustment</button></div></form>`)}
function wagerModal(tid){const t=S.teams.find(t=>t.id===tid);modal('A private wager.',`<form id="wager-form" data-team="${esc(tid)}"><p><b>${esc(t.name)}</b> · ${fmt(t.score)} points available. This amount is never shown on the projector before final judging.</p>${field('Points to wager','amount',0,'number',`min="0" max="${Math.max(0,t.score)}" required`)}<div class="modal-footer">${btn('Cancel','close')}<button class="primary" type="submit">Lock wager ${icon('lock')}</button></div></form>`)}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<55;i++){const el=document.createElement('i');el.className='confetti';el.style.left=Math.random()*100+'vw';el.style.background=['#d56143','#849d73','#d6b260','#344e46'][i%4];el.style.animationDelay=Math.random()*1.2+'s';document.body.append(el);setTimeout(()=>el.remove(),6000)}}
async function navigate(p){window.scrollTo(0,0);page=p;if(p==='history')historyItems=await api('/api/history');render()}
async function saveSettings(){const f=$('#settings-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.settings={timer:+d.timer,difficulty:d.difficulty,steal:+d.steal,doubleChance:+d.doubleChance,powers:f.elements.powers.checked,penalty:f.elements.penalty.checked};S=await api(`/api/room/${room}/settings`,d);render();toast('Your event settings are saved.')}
async function setRoom(code){stream?.close();room=code;history.replaceState({},'',location.pathname+'?room='+room);S=await api(`/api/room/${room}${mode==='host'?'':'/public'}`);subscribe();page='board';render()}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;try{
 if(a==='nav'){await navigate(b.dataset.page);return}
 if(a==='close'){close();return}
 if(a==='menu'){$('.sidebar').classList.toggle('open');return}
 if(a==='invite'){invite();return}
 if(a==='projector'){window.open('/projector?room='+room,'arch-projector');return}
 if(a==='fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();return}
 if(a==='sound'){sound=!sound;localStorage.setItem('arch_sound',sound);if(sound)beep();render();toast(sound?'Sound enabled on this screen.':'Sound muted on this screen.');return}
 if(a==='peek'){hostAnswer=!hostAnswer;render();return}
 if(a==='copyLink'){try{await navigator.clipboard.writeText(location.origin+'/join?room='+room);toast('Join link copied.')}catch{modal('Your join link',`<input readonly value="${esc(location.origin+'/join?room='+room)}" onclick="this.select()">`)}return}
 if(a==='categories'){categoriesModal();return}
 if(a==='teamEdit'){teamModal(b.dataset.id);return}
 if(a==='adjust'){adjustModal(b.dataset.team);return}
 if(a==='questionEdit'||a==='duplicate'){questionModal(b.dataset.id,a==='duplicate');return}
 if(a==='questionDelete'){confirmModal('Remove this question?','This removes it from this event’s question bank. Completed game history is preserved.','deleteQuestion:'+b.dataset.id);return}
 if(a==='teamDelete'){confirmModal('Remove this team?','Teams with audience participants cannot be removed.','deleteTeam:'+b.dataset.id);return}
 if(a==='manageCategories'){modal('Category studio.',`<p>Rename an existing category, or create a category for your campus, materials, or event special.</p><form id="category-form">${selectField('Category','id',[['','+ Create a new category'],...S.categories.map(c=>[c.id,c.name])],'')}${field('Category name','name','','text','required')}<button type="submit" class="primary">Save category</button></form>`);return}
 if(a==='export'){window.location.href='/api/room/'+room+'/export';return}
 if(a==='saveSettings'){await saveSettings();return}
 if(a==='newEvent'||a==='cloneEvent'){modal(a==='cloneEvent'?'Keep the setup. Start a new story.':'A new event begins here.',`<form id="new-event-form" data-copy="${a==='cloneEvent'?room:''}">${field('Event name','name',a==='cloneEvent'?S.name+' · Round 2':'Architecture Week','text','required')}<p>A unique room code and fresh scores will be created.${a==='cloneEvent'?' Your questions, teams, categories, and rules will be copied.':''}</p><button class="primary" type="submit">Create event ${icon('arrow')}</button></form>`);return}
 if(a==='switchEvent'){allRooms=await api('/api/rooms');modal('Your event collection.',`${allRooms.map(r=>`<div class="leader-row"><div style="flex:1"><b>${esc(r.name)}</b><small style="display:block;color:var(--muted);margin-top:5px">${esc(r.code)} · ${esc(r.phase)}</small></div>${btn('Open','openRoom','arrow','small',`data-room="${esc(r.code)}"`)}</div>`).join('')}`);return}
 if(a==='openRoom'){close();await setRoom(b.dataset.room);return}
 if(a==='refreshHistory'){historyItems=await api('/api/history');render();return}
 if(a==='downloadHistory'){const h=historyItems.find(h=>h.id===b.dataset.id);const blob=new Blob([JSON.stringify(h,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const l=document.createElement('a');l.href=url;l.download=h.code+'-results.json';l.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
 if(a==='historyLog'){const h=historyItems.find(h=>h.id===b.dataset.id);modal('The story of the scores.',h.log.length?h.log.map(l=>`<div class="leader-row">${esc(l.text)}</div>`).join(''):'<p>No scoring actions were recorded.</p>');return}
 if(a==='recovery'){const {key}=await api('/api/recovery');modal('Your private host recovery key.',`<p>This key grants full access to all of your events. Save it securely. Never share it with participants.</p><input readonly value="${esc(key)}" onclick="this.select()"><p>To recover access, open Event settings → Restore host access on your other device.</p>${btn('Download private key','downloadKey','download','primary',`data-key="${esc(key)}"`)}`);return}
 if(a==='downloadKey'){const url=URL.createObjectURL(new Blob(['ARCH ARENA — PRIVATE HOST RECOVERY KEY\nDo not share.\n\n'+b.dataset.key],{type:'text/plain'}));const l=document.createElement('a');l.href=url;l.download='arch-arena-private-recovery.txt';l.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
 if(a==='restore'){modal('Back to your studio.',`<form id="recovery-form">${field('Private recovery key','key','','password','required')}<button type="submit" class="primary">Restore host access</button></form>`);return}
 if(a==='rounds'){modal('Change the pace.',`<p>Take the competition beyond the quiz board.</p><div class="panel"><h2>${icon('bolt')} Rapid fire</h2><p>60 seconds for the active team. Host awards +100 per correct answer, then advances. Wrong answers score zero when penalties are off. Five seed prompts; add more to extend the bank.</p>${btn('Start rapid fire','special','','primary','data-mode="rapid"')}</div><div class="panel"><h2>${icon('pencil')} Draw it</h2><p>Sketch a courtyard house with a wind tower. 60 seconds, then host judging.</p>${btn('Start drawing round','special','','','data-mode="draw"')}</div><div class="panel"><h2>${icon('leaf')} Design challenge</h2><p>Design a shelter for the UAE desert in two minutes. Judge five criteria, up to 500 points per team.</p>${btn('Start design challenge','special','','','data-mode="design"')}</div>`);return}
 if(a==='special'){close();page='board';await action(b.dataset.mode);return}
 if(a==='wager'){wagerModal(b.dataset.team);return}
 if(a==='help'){modal('The host’s field guide.',`<div class="eyebrow">A smooth show in six steps</div><p><b>01 · Set the stage.</b> Rename teams, edit categories, and review your questions. Scores begin at zero.</p><p><b>02 · Invite your audience.</b> Share the QR code. Individual competitors can also be created as one-person teams.</p><p><b>03 · Extend your display.</b> Open Presentation mode on a second monitor or projector. Never mirror the host screen: it contains private controls and optional answer previews.</p><p><b>04 · Pick and play.</b> Click a point value. The timer starts immediately. Select the answering team, award correct, or offer a steal before revealing.</p><p><b>05 · Keep it fair.</b> Audience answers earn 100 points in their own leaderboard after reveal. Open answers are exact-match normalized; team responses are host-judged. Each power-up can be used once per team.</p><p><b>06 · Finish strong.</b> Collect secret wagers, reveal the final challenge, judge every team, then end the game. Rankings are saved to history.</p><p><b>Keyboard:</b> Escape closes dialogs. Space pauses/resumes an open timer. R reveals an answer. B returns to the board. These shortcuts only work on the host board, outside inputs.</p>`);return}
 if(a==='end'||a==='reset'||a==='final'){confirmModal(a==='end'?'Bring down the curtain?':a==='reset'?'Reset this game?':'Ready for the final challenge?',a==='end'?'Save the final rankings to game history and display the winner.':a==='reset'?'This clears scores, players, timers, used questions, and power-ups. This cannot be undone. Completed history is kept.':'Close the current round and collect a secret wager from every team.',a);return}
 if(a==='confirmed'){const act=b.dataset.confirm;close();if(act.startsWith('deleteQuestion:')){S=await api(`/api/room/${room}/question`,{delete:true,id:act.split(':')[1]});render()}else if(act.startsWith('deleteTeam:')){S=await api(`/api/room/${room}/teams`,{delete:true,id:act.split(':')[1]});render()}else {page='board';await action(act)}return}
 if(a==='chooseAnswer'){$$('#answer-form .answer-option').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');$('#chosen-answer').value=b.dataset.answer;return}
 if(a==='finalJudge'){await action(a,{team:b.dataset.team,correct:b.dataset.correct==='true'});return}
 const extra={};if(b.dataset.id)extra.id=b.dataset.id;if(b.dataset.team)extra.team=b.dataset.team;if(b.dataset.power)extra.power=b.dataset.power;await action(a,extra);
 }catch(e){toast(e.message)}});
document.addEventListener('submit',async ev=>{const f=ev.target;if(!f.id)return;ev.preventDefault();const button=$('[type=submit]',f);if(button)button.disabled=true;const d=Object.fromEntries(new FormData(f));try{
 if(f.id==='categories-form'){S=await api(`/api/room/${room}/settings`,{selected:new FormData(f).getAll('category')});close();render();toast('Your board has been curated.')}
 else if(f.id==='team-form'){S=await api(`/api/room/${room}/teams`,{...d,id:f.dataset.id});close();render();toast('Team saved.')}
 else if(f.id==='question-form'){d.id=f.dataset.id;d.options=d.options.split('\n').map(x=>x.trim()).filter(Boolean);d.points=+d.points;d.difficulty=+d.difficulty;d.timeLimit=+d.timeLimit;d.tolerance=+d.tolerance;S=await api(`/api/room/${room}/question`,{question:d});close();render();toast('Question saved to this event.')}
 else if(f.id==='category-form'){S=await api(`/api/room/${room}/category`,d);close();render();toast('Category saved. Add questions, then select it on the board.')}
 else if(f.id==='adjust-form'){await action('adjust',{team:d.team,amount:+d.amount});close()}
 else if(f.id==='new-event-form'){const res=await api('/api/rooms',{name:d.name,copy:f.dataset.copy||null});close();await setRoom(res.room);toast('Your new event is ready.')}
 else if(f.id==='recovery-form'){await api('/api/recovery',d);close();const b=await api('/api/bootstrap');await setRoom(b.room);toast('Host access restored.')}
 else if(f.id==='wager-form'||f.id==='player-wager-form'){await api(`/api/room/${room}/wager`,{amount:+d.amount,team:f.dataset.team});close();toast('Secret wager locked.')}
 else if(f.id==='join-form'){const code=d.room.trim().toUpperCase();if(!S||code!==room){room=code;S=await api(`/api/room/${room}/public`);renderJoin();$('#f-name').value=d.name;history.replaceState({},'','/join?room='+room);return}await api(`/api/room/${room}/join`,d);S=await api(`/api/room/${room}/public`);subscribe();renderPlayer()}
 else if(f.id==='answer-form'){if(!d.answer)throw Error('Choose an answer first.');await api(`/api/room/${room}/answer`,d);toast('Answer locked. Good luck!')}
 else if(f.id==='settings-form'){await saveSettings()}
 }catch(e){toast(e.message)}finally{if(button?.isConnected)button.disabled=false}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.id==='active-team')await action('active',{team:el.value});if(el.id==='library-category'){libraryCategory=el.value;$('#library-table').innerHTML=libraryTable()}if(el.dataset.upload&&el.files[0]){const fd=new FormData();fd.append('file',el.files[0]);el.disabled=true;const res=await fetch(`/api/room/${room}/upload`,{method:'POST',body:fd});const data=await res.json();if(!res.ok)throw Error(data.detail||'Upload failed.');$('#'+el.dataset.upload).value=data.url;if(el.dataset.upload==='questionImage')$('#image-preview').innerHTML=`<img class="preview-thumb" src="${esc(data.url)}" alt="Uploaded question image">`;toast('Image uploaded. Save the form to apply it.');el.disabled=false}}catch(e){el.disabled=false;toast(e.message)}});
document.addEventListener('input',ev=>{if(ev.target.id==='library-search'){libraryFilter=ev.target.value;$('#library-table').innerHTML=libraryTable()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();$('.sidebar')?.classList.remove('open')}if(mode!=='host'||page!=='board'||!S?.current||$('#modal-root').children.length||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();action('pause')}if(e.key.toLowerCase()==='r')action('reveal');if(e.key.toLowerCase()==='b')action('board')});
async function init(){try{if(mode==='host'){const b=await api('/api/bootstrap');if(!room)room=b.room;await setRoom(room)}else if(room){S=await api(`/api/room/${room}/public`);offset=S.serverNow-Date.now()/1000;if(mode==='projector'||S.me){subscribe();render()}else renderJoin()}else if(mode==='player')renderJoin();else $('#app').innerHTML=`<div class="loading">Room code required.<a href="/" style="font-size:14px;letter-spacing:0;margin-top:20px">Open host workspace →</a></div>`}catch(e){$('#app').innerHTML=`<div class="join-shell"><div class="join-main">${brand()}<h1>Let’s reconnect.</h1><p>${esc(e.message)}</p><a href="${mode==='player'?'/join':'/'}"><button class="primary">${mode==='player'?'Enter room code':'Open your workspace'}</button></a></div></div>`}}
init();
